    for pair in line.split(','):
        if ':' not in pair:
            raise AnsibleError("failed to parse jinja2 override '%s'."
                               " Did you use something different from colon as key-value separator?" % pair.strip())
        (key, val) = pair.split(':', 1)
        key = key.strip()
